#include <bits/stdc++.h>

using namespace std;

using LL = long long;

template <typename T>
inline void read(T &x) {
    T f = 1;
    x = 0;
    int c = getchar();
    while (c != EOF && !isdigit(c)) {
        if (c == '-') f = -f;
        c = getchar();
    }
    while (c != EOF && isdigit(c)) {
        x = x * 10 + c - '0';
        c = getchar();
    }
    x *= f;
}

const int K = 5010;
const int mod = 998244353;

int n, m, k;
int fac[K], ifac[K], S[K][K];

inline void inc(int &x, int y) {
    x += y;
    if (x >= mod) x -= mod;
}

inline int quickpow(int a, int exponent) {
    int res = 1;
    while (exponent > 0) {
        if (exponent & 1) res = static_cast<LL>(res) * a % mod;
        a = static_cast<LL>(a) * a % mod;
        exponent >>= 1;
    }
    return res;
}

int main() {
    read(n);
    read(m);
    read(k);

    fac[0] = 1;
    for (int i = 1; i <= k; ++i)
        fac[i] = static_cast<LL>(fac[i - 1]) * i % mod;

    ifac[k] = quickpow(fac[k], mod - 2);
    for (int i = k - 1; i >= 0; --i)
        ifac[i] = static_cast<LL>(ifac[i + 1]) * (i + 1) % mod;

    S[0][0] = 1;
    for (int i = 1; i <= k; ++i) {
        for (int j = 1; j <= i; ++j) {
            S[i][j] = (S[i - 1][j - 1] +
                       static_cast<LL>(S[i - 1][j]) * j) % mod;
        }
    }

    int coef = 1;
    int ans = 0;
    int limit = min(k, n);
    int base = (quickpow(m - 1, mod - 2) + 1) % mod;

    for (int i = 0; i <= limit; ++i) {
        if (i)
            coef = static_cast<LL>(coef) * (n - i + 1) % mod;

        int term = static_cast<LL>(S[k][i]) * coef % mod;
        term = static_cast<LL>(term) * quickpow(m - 1, n - i) % mod;
        term = static_cast<LL>(term) * quickpow(base, n - i) % mod;
        inc(ans, term);
    }

    ans = static_cast<LL>(ans) *
          quickpow(quickpow(m, n), mod - 2) % mod;

    printf("%d\n", ans);
    return 0;
}

